// SPA router + all site pages.
import * as THREE from 'three';
import { api, state, refreshMe, loadCatalog, catalogItem, toast, esc, fmtNum, openWS } from './api.js';
import { avatarSVG, faceDataURL } from './avatar2d.js';
import { GameClient } from './engine/game.js';
import { Studio } from './studio/studio.js';
import { Character } from './engine/player.js';

const page = document.getElementById('page');
const nav = document.getElementById('topnav');
let activeApp = null; // running GameClient or Studio

// ---------------- router ----------------
const routes = [
  [/^#?\/?$/, renderHome],
  [/^#\/discover/, renderDiscover],
  [/^#\/game\/([\w-]+)/, renderGamePage],
  [/^#\/play\/([\w-]+)/, renderPlay],
  [/^#\/studio\/([\w-]+)/, renderStudio],
  [/^#\/studio/, renderStudioList],
  [/^#\/avatar/, renderAvatar],
  [/^#\/catalog/, renderCatalog],
  [/^#\/friends/, renderFriends],
  [/^#\/profile\/([\w-]+)/, renderProfile],
];

async function route() {
  if (activeApp) { const a = activeApp; activeApp = null; a.exit && a.alive && a.exit(); }
  page.className = '';
  document.body.style.overflow = '';

  if (!state.me) {
    renderAuth();
    return;
  }
