  updateNavUser();

  const hash = location.hash || '#/';
  for (const [re, fn] of routes) {
    const m = hash.match(re);
    if (m) {
      document.querySelectorAll('#topnav [data-nav]').forEach((a) => {
        a.classList.toggle('active', hash.startsWith(a.getAttribute('href')) && a.getAttribute('href') !== '#/' || (a.getAttribute('href') === '#/' && (hash === '#/' || hash === '')));
      });
      try {
        await fn(...m.slice(1));
      } catch (e) {
        page.innerHTML = `<div class="empty-note">⚠️ ${esc(e.message)}</div>`;
