  document.getElementById('nav-profile').href = '#/profile/' + state.me.username;
}

document.getElementById('nav-logout').onclick = async () => {
  await api('/logout', { method: 'POST', body: {} });
  state.me = null;
  location.hash = '#/';
  route();
};

