  nav.classList.add('hidden');
  page.className = 'full';
  page.innerHTML = `
    <div class="auth-wrap">
      <div class="auth-logo">
        <div class="big-block"></div>
        <h1>GLINT</h1>
        <p>Research's Legally Distinct Clone</p>
        <p style="font-size:13px;margin-top:6px">Play together. Build together. Definitely not that other site.</p>
      </div>
      <div class="panel auth-card">
        <div class="tabs">
          <button id="tab-login" class="active">Log in</button>
          <button id="tab-register">Sign up</button>
        </div>
        <div class="err" id="auth-err"></div>
        <label class="fld">Username<input type="text" id="auth-user" maxlength="20" autocomplete="username"></label>
