        <p style="color:var(--dim);font-size:12px;margin-top:12px" id="auth-hint">New here? Sign up — you get 250 ◈ Glimmers free.</p>
      </div>
    </div>
  `;
  let mode = 'login';
  const setMode = (m) => {
    mode = m;
    document.getElementById('tab-login').classList.toggle('active', m === 'login');
    document.getElementById('tab-register').classList.toggle('active', m === 'register');
    document.getElementById('auth-go').textContent = m === 'login' ? 'Log in' : 'Create account';
