let avatarPreview = null;

function startAvatarPreview(canvas) {
  const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
  renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x142733);
  scene.add(new THREE.AmbientLight(0xffffff, 1.2));
  const key = new THREE.DirectionalLight(0xffffff, 1.8);
  key.position.set(3, 5, 4);
  scene.add(key);
  const camera = new THREE.PerspectiveCamera(45, 1, 0.1, 50);
  camera.position.set(0, 0.4, 6.5);
  camera.lookAt(0, 0, 0);
  const stand = new THREE.Mesh(
    new THREE.CylinderGeometry(1.6, 1.8, 0.3, 32),
    new THREE.MeshStandardMaterial({ color: 0x224050 })
  );
  stand.position.y = -2.6;
  scene.add(stand);

  const ctx = { renderer, scene, camera, char: null, alive: true };
  const animate = () => {
    if (!ctx.alive) return;
    requestAnimationFrame(animate);
    const w = canvas.clientWidth, h = canvas.clientHeight;
    if (canvas.width !== w * renderer.getPixelRatio()) {
      renderer.setSize(w, h, false);
      camera.aspect = w / Math.max(1, h);
      camera.updateProjectionMatrix();
    }
    if (ctx.char) {
      ctx.char.group.rotation.y += 0.008;
      ctx.char.animate(0.016, 'idle');
    }
    renderer.render(scene, camera);
  };
  animate();
  return ctx;
}

function setPreviewAvatar(av) {
  if (!avatarPreview) return;
  if (avatarPreview.char) avatarPreview.char.dispose();
  avatarPreview.char = new Character(av, null, state.catalog);
  avatarPreview.char.group.position.y = -0.3;
  avatarPreview.scene.add(avatarPreview.char.group);
}

async function renderAvatar() {
  await loadCatalog();
  if (avatarPreview) { avatarPreview.alive = false; avatarPreview = null; }
  const draft = JSON.parse(JSON.stringify(state.me.avatar));
  const BODY_PARTS = [['head', 'Head'], ['torso', 'Torso'], ['leftArm', 'L Arm'], ['rightArm', 'R Arm'], ['leftLeg', 'L Leg'], ['rightLeg', 'R Leg']];
  const COLORS = ['#ffd23f', '#ffb74d', '#e8a87c', '#bf8a65', '#8d5e3c', '#e54b4b', '#f0a020', '#3aa14f', '#19ff8c', '#2a7de1', '#19c2ff', '#8a4fff', '#ff5e9c', '#cfd8dc', '#78909c', '#37474f', '#ffffff', '#1b1b1b'];

  const ownedHats = state.catalog.filter((i) => i.type === 'hat' && state.me.inventory.includes(i.id));
  const ownedFaces = state.catalog.filter((i) => i.type === 'face' && state.me.inventory.includes(i.id));

  page.innerHTML = `
    <h1>Avatar</h1>
    <p class="sub">Dress your blocky self. Changes show up in every game.</p>
    <div class="avatar-layout">
      <div class="avatar-preview"><canvas></canvas></div>
      <div style="flex:1;min-width:300px">
        <h2 style="margin-top:0">Body Colors</h2>
        <div id="av-body"></div>
        <h2>Face</h2>
        <div class="item-grid" id="av-faces"></div>
        <h2>Hats <a href="#/catalog" style="font-size:13px;font-weight:400">— get more in the Catalog</a></h2>
        <div class="item-grid" id="av-hats"></div>
        <button class="btn big green" id="av-save" style="margin-top:18px">Save Avatar</button>
      </div>
    </div>
  `;

  avatarPreview = startAvatarPreview(page.querySelector('.avatar-preview canvas'));
  setPreviewAvatar(draft);

  const bodyEl = document.getElementById('av-body');
  let selPart = 'torso';
  const renderBody = () => {
    bodyEl.innerHTML = `
      <div class="row" style="margin-bottom:8px">${BODY_PARTS.map(([k, label]) =>
        `<button class="tool-btn${selPart === k ? ' active' : ''}" data-part="${k}">${label}</button>`).join('')}</div>
      <div class="color-swatches">${COLORS.map((c) =>
        `<span class="swatch${draft.bodyColors[selPart] === c ? ' sel' : ''}" data-c="${c}" style="background:${c}"></span>`).join('')}</div>
    `;
    bodyEl.querySelectorAll('[data-part]').forEach((b) => b.onclick = () => { selPart = b.dataset.part; renderBody(); });
    bodyEl.querySelectorAll('[data-c]').forEach((s) => s.onclick = () => {
      draft.bodyColors[selPart] = s.dataset.c;
      renderBody();
      setPreviewAvatar(draft);
    });
  };
  renderBody();

  const facesEl = document.getElementById('av-faces');
  const hatsEl = document.getElementById('av-hats');
  const renderItems = () => {
    facesEl.innerHTML = ownedFaces.map((i) => `
      <div class="item-card${draft.face === i.id ? ' equipped' : ' owned'}" data-id="${i.id}">
        <div class="item-thumb"><img src="${faceDataURL(i.face, 80, '#ffd23f')}" width="64"></div>
        <div class="item-name">${esc(i.name)}</div>
        <button class="btn dark" style="margin-top:6px">${draft.face === i.id ? 'Equipped' : 'Equip'}</button>
      </div>`).join('');
    hatsEl.innerHTML = `
      <div class="item-card${!draft.hat ? ' equipped' : ' owned'}" data-id="">
        <div class="item-thumb" style="font-size:34px">🚫</div>
        <div class="item-name">No Hat</div>
        <button class="btn dark" style="margin-top:6px">${!draft.hat ? 'Equipped' : 'Equip'}</button>
      </div>` + ownedHats.map((i) => `
      <div class="item-card${draft.hat === i.id ? ' equipped' : ' owned'}" data-id="${i.id}">
        <div class="item-thumb"><span style="font-size:30px;color:${i.mesh.color}">⬢</span></div>
        <div class="item-name">${esc(i.name)}</div>
        <button class="btn dark" style="margin-top:6px">${draft.hat === i.id ? 'Equipped' : 'Equip'}</button>
      </div>`).join('');
    facesEl.querySelectorAll('.item-card').forEach((c) => c.onclick = () => {
      draft.face = c.dataset.id; renderItems(); setPreviewAvatar(draft);
    });
    hatsEl.querySelectorAll('.item-card').forEach((c) => c.onclick = () => {
      draft.hat = c.dataset.id || null; renderItems(); setPreviewAvatar(draft);
    });
  };
  renderItems();

  document.getElementById('av-save').onclick = async () => {
    const r = await api('/avatar', { body: draft });
    state.me.avatar = r.avatar;
    updateNavUser();
    toast('Avatar saved ✓');
  };
}

